"""Normalize all 84 retained legacy HTML cards. Never modifies the originals."""
import json
from pathlib import Path
from html.parser import HTMLParser
import re

ROOT=Path(__file__).resolve().parents[4]
HERE=Path(__file__).resolve().parent
SOURCES=json.loads((HERE/'legacy-source-extraction.json').read_text())
SCREENS={}

class Element:
 def __init__(self,tag='root',attrs=()):self.tag=tag;self.attrs=dict(attrs);self.children=[];self.text=[]
 @property
 def classes(self):return self.attrs.get('class','').split()
 def all(self):
  out=[]
  for c in self.children:out.append(c);out.extend(c.all())
  return out
 def words(self):return ' '.join(self.text+sum((c.words().split() for c in self.children),[])).strip()
class SourceTree(HTMLParser):
 def __init__(self):super().__init__();self.root=Element();self.stack=[self.root]
 def handle_starttag(self,t,a):
  e=Element(t,a);self.stack[-1].children.append(e)
  if t not in {'img','meta','link','br','hr','input','source','wbr'}:self.stack.append(e)
 def handle_startendtag(self,t,a):self.stack[-1].children.append(Element(t,a))
 def handle_endtag(self,t):
  for i in range(len(self.stack)-1,0,-1):
   if self.stack[i].tag==t:self.stack=self.stack[:i];break
 def handle_data(self,v):
  if v.strip():self.stack[-1].text.append(v.strip())

def source_cells(path):
 parser=SourceTree();parser.feed(path.read_text());nodes=parser.root.all()
 def cells_of(container,cls):
  result=[]
  for e in container.all():
   if cls not in e.classes:continue
   desc=e.all();use=next((c for c in desc if c.tag=='use'),None)
   href=use.attrs.get('href','') if use else ''
   counts=[c.words() for c in desc if 'count' in c.classes or 'ct' in c.classes]
   rarity=next((c.attrs.get('class','').split('dot-')[-1].split()[0] for c in desc if any(k.startswith('dot-') for k in c.classes)),None)
   labels=[c.words() for c in desc if 'name' in c.classes or 'fn' in c.classes or (cls=='gr-slot' and 'nm' in c.classes)]
   ishidden='is-hidden' in e.classes
   state='Empty' if 'is-empty' in e.classes or 'is-ghost' in e.classes else 'Tasted' if 'is-tasted' in e.classes else 'Silhouette' if 'is-off' in e.classes else 'Unknown' if ishidden else 'Discovered' if 'is-page' in e.classes or cls=='b2-fc' else ''
   if any('is-lock' in c.classes for c in desc):state='Locked'
   result.append({'icon':href.split('#')[-1] if href else None,'sourceSprite':str((path.parent/href.split('#')[0]).resolve().relative_to(Path.cwd())) if href else None,'count':re.sub(r'^[×x]','',counts[0]) if counts else None,'rarity':rarity,'selected':'is-selected' in e.classes or 'is-sel' in e.classes,'empty':'is-empty' in e.classes or 'is-ghost' in e.classes,'state':state,'label':labels[0] if labels else '', 'sourceClasses':e.classes,'badges':[c.words() for c in desc if 'cap-s' in c.classes],'familyIcons':[c.attrs.get('href','').split('#')[-1] for pip in desc if 'pip' in pip.classes for c in pip.all() if c.tag=='use'],'source':'Farm Storage' if any('b2-house' in c.classes for c in desc) else '', 'hint':' '.join(c.words() for c in desc if 'hint' in c.classes),'region':' '.join(c.words() for c in desc if 'rg' in c.classes),'slot':' '.join(c.words() for c in desc if 'act' in c.classes),'new':'is-new' in e.classes})
  return result
 grids=[cells_of(e,'cell') for e in nodes if 'grid' in e.classes]
 quick=[cells_of(e,'slot') for e in nodes if 'slots' in e.classes]
 collections=[]
 for i,e in enumerate([e for e in nodes if 'b2-dex' in e.classes]):
  cells=cells_of(e,'b2-fc')
  for c in cells:c['rarity']=['common','fine','rare','legendary'][i]
  collections.append({'rarity':['common','fine','rare','legendary'][i],'items':cells})
 gear=[c for e in nodes if 'gr-slots' in e.classes for c in cells_of(e,'gr-slot')]
 return grids,quick,collections,gear

def a(label,target,kind='navigate',feedback=None):
    d=dict(label=label,target=target,kind=kind)
    if feedback:d['feedback']=feedback
    return d
def fact(label,value,kind='progress'):return dict(label=label,value=str(value),kind=kind)
def req(label,have,need):return dict(label=label,have=have,need=need)
def row(title,state='',effect='',quantity=None,facts=None,requirements=None,actions=None,supporting='',disclosure=None,**extra):
    d=dict(title=title,state=state,effect=effect,keyFacts=facts or [],requirements=requirements or [],supporting=supporting,disclosure=disclosure or [],actions=actions or [])
    if quantity is not None:d['quantity']=dict(value=str(quantity),label='Owned')
    d.update(extra);return d
def add(id,title,layout='sheet',**kw):
    d=row(title,**kw);d['id']=id;d['layout']=layout;SCREENS[id]=d;return d
def examples(id,states):SCREENS[id]['stateExamples']=states

