LIVE=json.loads((HERE/'before-inventory.json').read_text())
LIVE_CARDS={x['id']:x for x in LIVE['cards']}
ALIASES={'TRAVEL-FREE-1':'MAP-2-FREE','TRAVEL-PAID-1':'MAP-4-PAID','SOC-GIFT-1':'SOC-5','SOC-VISIT-1':'SOC-6','CROP-1':'FISH-6'}
def clean_links(value):
 if isinstance(value,dict):
  if 'target' in value:
   original=value['target']
   value['target']=ALIASES.get(original,original)
   if original=='CROP-1':value['targetTab']='Crop-dex'
   if value.get('label')=='Choose recipient':value['target']='SOC-5'
  for child in value.values():clean_links(child)
 elif isinstance(value,list):
  for child in value:clean_links(child)

SCREENS['COOK-4']['keyFacts']=[fact('Cooking XP','30','reward'),fact('Cookbook','2/48','progress')]
SCREENS['COOK-4']['disclosure'].append('20 first-cooked XP + 10 quality-adjusted Cooking XP.')
SCREENS['FISH-3']['quantity']['label']='Caught'
SCREENS['COOK-4']['quantity']['label']='Portions'
SCREENS['COOK-6']['quantity']['label']='Portions'
SCREENS['PROFILE-2']['items'][2]['keyFacts']=[fact('Collected','14/20','progress')]

shop_ids={'FARM-6','FARM-6-2','NPC-2','NPC-2-2','NPC-3','NPC-3-2'}
for id,s in SCREENS.items():
 if id in shop_ids:s['variant']='shop-with-bag'
 elif id=='COOK-2a':s['variant']='cookbook-with-scene-pot'
 elif id=='COOK-2b':s['variant']='experiment-with-scene-pot'
 elif id=='FISH-6':s['variant']='collection-grid'
 elif id=='BAG-2-2':s['variant']='materials-and-storage'
 elif s['layout']=='inventory':s['variant']='bag'
 elif s['layout']=='gear':s['variant']='gear'
 elif s['layout']=='states':s['variant']='state-sheet'
 else:s['variant']=s['layout']
 clean_links(s)

base=Path('docs/design/ui-anchors-2026-10-03')
for source in SOURCES:
 id=source['title'].split(' · ')[0]
 if id not in SCREENS:raise RuntimeError(f'Missing semantic descriptor: {id}')
 s=SCREENS[id]
 s['canonicalName']=source['title']
 s['sourceHtml']=source['file']
 live=LIVE_CARDS[id]
 s['sourceGroup']=live['section'][:2]
 s['figmaNodeId']=live['nodeId']
 s['figmaSectionId']=live['sectionId']
 s['figmaSectionName']=live['section']
 s['sourceKind']='native-revision' if id=='COOK-3-2' else 'raster-card'
 p=Path(source['file'])
 grids,quick,collection,gear=source_cells(p)
 s['gridCells']=grids[0] if grids else []
 s['quickSlots']=quick[0] if quick else []
 s['gridItems']=s['gridCells']
 s['quickItems']=s['quickSlots']
 s['collectionGroups']=collection
 if collection:s['gridItems']=[c for g in collection for c in g['items']]
 s['gearSlots']=gear
 s['gridColumns']=5
 s['gridVisibleCount']=len(s['gridItems'])
 s['quickEndAction']='Close' if s['layout'] in ['inventory','gear'] and quick else 'Bag' if quick else None
 s['layoutSpecialization']={'type':s['variant'],'gridColumns':5,'preserveOriginalEmptySlots':True,'nativeUIOnly':True,'sceneRasterAllowed':True,'stateExamplesSeparate':bool(s.get('stateExamples')),'sourceVisibleCells':len(s['gridItems'])}
 if len(grids)>1:s['sourceGridVariants']=grids
 if len(quick)>1:s['sourceQuickVariants']=quick
 s['scene']=str((p.parent/source['images'][0]).resolve().relative_to(Path.cwd())) if source['images'] else None
 s['sceneName']=Path(s['scene']).stem if s['scene'] else None
 shot=base/'out'/('batch2' if '/batch2/' in source['file'] else 'batch1')/(id+'.png')
 if id in ['FARM-1','FISH-1','COOK-1','BAG-1']:shot=base/'out/current'/(id+'.png')
 s['sourceScreenshot']=str(shot) if shot.exists() else None
 s['sourceNote']=s.get('sourceNote','Source layouts and imagery retained; identity, state, quantities, facts, requirements and actions are separated into reusable native components.')
 s['originalVisibleText']=source['text']
 s['rebuildStatus']='normalized-for-native-rebuild'
 s['reviewedEvidence']=['HTML source', 'legacy contact sheets / source image when available','gameplay v2 §1.5 latest amendments']

assert len(SCREENS)==84
assert not {'NPC-G1-5','EQUIP-1','COOK-5'} & SCREENS.keys()
legacy_live={s['id'] for s in LIVE['cards'] if s['section'][:2] in ['00','01','02','03','04','05','06']}
assert legacy_live==SCREENS.keys(),(legacy_live-SCREENS.keys(),SCREENS.keys()-legacy_live)
(HERE/'legacy-screens.json').write_text(json.dumps(list(SCREENS.values()),ensure_ascii=False,indent=2)+'\n')
print(f'Wrote {len(SCREENS)} screens; {sum(len(s.get("stateExamples",[])) for s in SCREENS.values())} retained state examples.')
